INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('00594c19-0000-4000-8000-000000594c19', '2dfcfb72-0000-4000-8000-00002dfcfb72', 'IR', 'communications', 'communications', 'Identifier le destinataire', 3, 3, 'Vous êtes AER452, cap 240. L''ATC dit « AER425, cap 270 ». Quel état retenir pour AER452 ?', 'You are AER452, heading 240. ATC says “AER425, heading 270”. Which state applies to AER452?', '["Cap 240, instruction adressée à un autre avion", "Cap 270, dernière instruction sur la fréquence", "Cap 270 après collationnement avec AER452", "Cap 255, moyenne en attendant confirmation"]', '["Heading 240, instruction addressed to another aircraft", "Heading 270, latest instruction on frequency", "Heading 270 after reading back as AER452", "Heading 255, average pending confirmation"]', 'Cap 240, instruction adressée à un autre avion', 'Les chiffres de l''indicatif sont transposés : le destinataire est différent. Un collationnement fait au nom d''AER452 ne transfère pas la clairance ; aucune moyenne n''est autorisée.

![IR_090_001](/illustrations/ir-090-001.svg)', 'The callsign digits are transposed: this is another addressee. Reading back as AER452 does not transfer clearance; no averaged heading was assigned.

![IR_090_001](/illustrations/en/ir-090-001.svg)', '["IR", "exam-mcq", "exam-subject:090"]')
