INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('00594c1a-0000-4000-8000-000000594c1a', '2dfcfb72-0000-4000-8000-00002dfcfb72', 'IR', 'communications', 'communications', 'Identifier le destinataire', 3, 3, 'Message : AER452, cap 260, descendez [masqué], QNH 1006. Quelle information doit être demandée avant d''utiliser le nouveau niveau ?', 'Message: AER452, heading 260, descend [blocked], QNH 1006. Which information must be requested before using the new level?', '["Confirmation de 3 000 ft parce que prévu au briefing", "Confirmation du QNH déjà reçu uniquement", "Le niveau du trafic précédent comme substitut", "La valeur du niveau de descente"]', '["Confirmation of 3,000 ft because it was briefed", "Only confirmation of the already received QNH", "The preceding aircraft''s level as a substitute", "The descent-level value"]', 'La valeur du niveau de descente', 'Le niveau n''a pas été reçu. Le QNH et le cap ne permettent pas de le déduire ; une attente de briefing ne fournit pas de clairance. Demander la répétition de l''élément manquant.

![IR_090_001](/illustrations/ir-090-001.svg)', 'The level was not received. QNH and heading cannot determine it; a briefing expectation supplies no clearance. Request repetition of the missing item.

![IR_090_001](/illustrations/en/ir-090-001.svg)', '["IR", "exam-mcq", "exam-subject:090"]')
