INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('00594c1b-0000-4000-8000-000000594c1b', '2dfcfb72-0000-4000-8000-00002dfcfb72', 'IR', 'communications', 'communications', 'Identifier le destinataire', 3, 3, 'AER452 demande une montée ; réponse STANDBY. Quelle mise à jour du niveau autorisé inscrire ?', 'AER452 requests a climb; reply is STANDBY. What update belongs in the cleared-level record?', '["Inscrire le niveau demandé après trente secondes", "Considérer toute future montée comme refusée", "Aucune, conserver le niveau précédemment autorisé", "Remplacer par le niveau demandé"]', '["Enter the requested level after thirty seconds", "Treat any future climb as refused", "None, retain the previously cleared level", "Replace it with the requested level"]', 'Aucune, conserver le niveau précédemment autorisé', 'STANDBY laisse la demande en attente, sans nouveau niveau ni délai automatique d''acceptation. Ce n''est pas non plus un refus définitif.

![IR_090_001](/illustrations/ir-090-001.svg)', 'STANDBY leaves the request pending, without a new level or automatic acceptance delay. Nor is it a final denial.

![IR_090_001](/illustrations/en/ir-090-001.svg)', '["IR", "exam-mcq", "exam-subject:090"]')
