INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('00594fdd-0000-4000-8000-000000594fdd', '2dfcfb72-0000-4000-8000-00002dfcfb72', 'IR', 'communications', 'communications', 'Collationner les éléments de sécurité', 3, 3, 'Instruction : cap 230, maintenez 5 000 ft, QNH 1008, AER452. Quel collationnement est complet et fidèle ?', 'Instruction: heading 230, maintain 5,000 ft, QNH 1008, AER452. Which readback is complete and accurate?', '["Cap 230, QNH 1008, AER452", "Cap 230, maintenons 5 000 ft, QNH 1008, AER452", "Cap 230, maintenons 5 000 ft, AER452", "Cap 230, maintenons 5 000 ft, QNH 1018, AER452"]', '["Heading 230, QNH 1008, AER452", "Heading 230, maintaining 5,000 ft, QNH 1008, AER452", "Heading 230, maintaining 5,000 ft, AER452", "Heading 230, maintaining 5,000 ft, QNH 1018, AER452"]', 'Cap 230, maintenons 5 000 ft, QNH 1008, AER452', 'Comparer présence et valeur de chaque élément. Deux réponses omettent calage ou niveau ; une autre remplace 1008 par 1018. La bonne identification seule ne rend pas ces réponses complètes.

![IR_090_001](/illustrations/ir-090-001.svg)', 'Check both presence and value of every item. Two replies omit setting or level; another substitutes 1018 for 1008. Correct identification alone does not make them complete.

![IR_090_001](/illustrations/en/ir-090-001.svg)', '["IR", "exam-mcq", "exam-subject:090"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('00594fde-0000-4000-8000-000000594fde', '2dfcfb72-0000-4000-8000-00002dfcfb72', 'IR', 'communications', 'communications', 'Collationner les éléments de sécurité', 3, 3, 'Code assigné 4621. Le pilote sélectionne 4621 mais annonce 4612. Quel écart reste à traiter ?', 'Assigned squawk 4621. The pilot selects 4621 but reads back 4612. What discrepancy remains?', '["Le code collationné doit être corrigé à 4621", "Aucun puisque le code sélectionné est correct", "Changer la sélection à 4612 pour l''accorder au message", "Changer de canal pour vérifier le code"]', '["The read-back code must be corrected to 4621", "None because the selected code is correct", "Select 4612 to match the reply", "Change channel to check the code"]', 'Le code collationné doit être corrigé à 4621', 'L''action correcte dans le cockpit ne rend pas fidèle le collationnement entendu par l''ATC. Corriger la parole selon l''instruction, plutôt que modifier une sélection juste pour suivre l''erreur verbale.

![IR_090_001](/illustrations/ir-090-001.svg)', 'Correct cockpit selection does not make the readback heard by ATC accurate. Correct the spoken reply to the instruction rather than changing a correct selection to match the verbal error.

![IR_090_001](/illustrations/en/ir-090-001.svg)', '["IR", "exam-mcq", "exam-subject:090"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('00594fdf-0000-4000-8000-000000594fdf', '2dfcfb72-0000-4000-8000-00002dfcfb72', 'IR', 'communications', 'communications', 'Collationner les éléments de sécurité', 3, 3, 'Nouveau canal 128.305, collationnement 128.350. Que faut-il résoudre avant transfert ?', 'New channel 128.305, readback 128.350. What must be resolved before transfer?', '["Seulement le nom de la station", "Aucun écart puisque les trois premiers chiffres coïncident", "Le canal précédent doit remplacer les deux valeurs", "La transposition 305/350"]', '["Only the station name", "No discrepancy because the first three digits match", "The previous channel must replace both values", "The 305/350 transposition"]', 'La transposition 305/350', 'Comparer l''intégralité du canal : une terminaison différente mène à une autre sélection. Le nom de station ou les chiffres initiaux ne valident pas la valeur reçue.

![IR_090_001](/illustrations/ir-090-001.svg)', 'Compare the complete channel: a different ending changes selection. Station name or matching initial digits cannot validate the received value.

![IR_090_001](/illustrations/en/ir-090-001.svg)', '["IR", "exam-mcq", "exam-subject:090"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('00594fe0-0000-4000-8000-000000594fe0', '2dfcfb72-0000-4000-8000-00002dfcfb72', 'IR', 'communications', 'communications', 'Collationner les éléments de sécurité', 3, 3, 'Instruction : roulez via A, maintenez avant piste 18. Réponse : via A, traversons 18. Quelle erreur modifie la portée ?', 'Instruction: taxi via A, hold short runway 18. Reply: via A, crossing 18. Which error changes scope?', '["La piste 18 est devenue piste 36", "Le seul défaut est l''absence de vitesse", "La traversée remplace le maintien avant piste", "La voie A est devenue inconnue"]', '["Runway 18 became runway 36", "The only defect is missing speed", "Crossing replaces holding short", "Taxiway A has become unknown"]', 'La traversée remplace le maintien avant piste', 'La route de roulage et le numéro sont conservés, mais le verbe autorise à tort une autre action. La correction doit rétablir maintien avant piste, pas simplement répéter son numéro.

![IR_090_001](/illustrations/ir-090-001.svg)', 'Taxi route and runway number match, but the verb wrongly substitutes another action. Correction must restore hold short, not merely repeat the runway number.

![IR_090_001](/illustrations/en/ir-090-001.svg)', '["IR", "exam-mcq", "exam-subject:090"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('005953a2-0000-4000-8000-0000005953a2', '2dfcfb72-0000-4000-8000-00002dfcfb72', 'IR', 'communications', 'communications', 'Fermer la boucle', 3, 3, 'AER452 : cap 240, 5 000 ft, 180 kt. Puis « cap 260, correction, cap 250 ». Aucun autre changement. État autorisé ?', 'AER452: heading 240, 5,000 ft, 180 kt. Then “heading 260, correction, heading 250”. No other change. Cleared state?', '["240 / 5 000 ft / 180 kt", "250 / 5 000 ft / 180 kt", "260 / 5 000 ft / 180 kt", "250 / 2 500 ft / 180 kt"]', '["240 / 5,000 ft / 180 kt", "250 / 5,000 ft / 180 kt", "260 / 5,000 ft / 180 kt", "250 / 2,500 ft / 180 kt"]', '250 / 5 000 ft / 180 kt', 'La correction remplace 260 par 250 ; elle ne transforme pas les chiffres du cap en niveau. 240 est l''ancien cap, désormais modifié. Niveau et vitesse restent inchangés.

![IR_090_001](/illustrations/ir-090-001.svg)', 'Correction replaces 260 with 250; heading digits do not become a level. 240 is the previous, amended heading. Level and speed remain unchanged.

![IR_090_001](/illustrations/en/ir-090-001.svg)', '["IR", "exam-mcq", "exam-subject:090"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('005953a3-0000-4000-8000-0000005953a3', '2dfcfb72-0000-4000-8000-00002dfcfb72', 'IR', 'communications', 'communications', 'Fermer la boucle', 3, 3, 'Instruction : cap 210, QNH 1013, code 5274. Réponse : cap 210, QNH 1031, AER452. Quels défauts détecter ?', 'Instruction: heading 210, QNH 1013, squawk 5274. Reply: heading 210, QNH 1031, AER452. Which defects are present?', '["QNH substitué et code omis", "Cap erroné et QNH correct", "Code erroné mais présent", "QNH seul, puisque le code peut être omis"]', '["Substituted QNH and omitted code", "Wrong heading and correct QNH", "Wrong but present code", "Only QNH, because code can be omitted"]', 'QNH substitué et code omis', '1013 est devenu 1031 et 5274 n''a pas été répété. Détecter une erreur ne doit pas arrêter la recherche d''une seconde ; omission et substitution demandent toutes deux une correction.

![IR_090_001](/illustrations/ir-090-001.svg)', '1013 became 1031 and 5274 was not repeated. Finding one error must not stop the search for another; omission and substitution both need repair.

![IR_090_001](/illustrations/en/ir-090-001.svg)', '["IR", "exam-mcq", "exam-subject:090"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('005953a4-0000-4000-8000-0000005953a4', '2dfcfb72-0000-4000-8000-00002dfcfb72', 'IR', 'communications', 'communications', 'Fermer la boucle', 3, 3, 'Exercice : vitesse minimale de configuration 160 kt, ATC demande 150 kt. Quel message expose correctement la contrainte ?', 'Exercise: configuration minimum speed 160 kt, ATC requests 150 kt. Which message correctly exposes the constraint?', '["WILCO 150, puis maintenir 160 sans annonce", "ROGER 150, puis attendre une détection ATC", "Collationner 160 comme si ce chiffre avait été assigné", "UNABLE 150, minimum 160 dans cette configuration, demandons 160"]', '["WILCO 150, then maintain 160 silently", "ROGER 150, then wait for ATC detection", "Read back 160 as if it had been assigned", "UNABLE 150, minimum 160 in this configuration, request 160"]', 'UNABLE 150, minimum 160 dans cette configuration, demandons 160', 'Annoncer impossibilité, raison et proposition distingue une demande d''une clairance. Les autres réponses masquent la non-exécution ou transforment un chiffre proposé en instruction reçue.

![IR_090_001](/illustrations/ir-090-001.svg)', 'Stating inability, reason and proposal distinguishes a request from clearance. Other replies conceal non-compliance or turn a proposed number into a received instruction.

![IR_090_001](/illustrations/en/ir-090-001.svg)', '["IR", "exam-mcq", "exam-subject:090"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('0ad12014-0000-4000-8000-00000ad12014', '2dfcfb72-0000-4000-8000-00002dfcfb72', 'IR', 'communications', 'communications', 'Fermer la boucle', 3, 3, 'Votre collationnement était 4 000 ft ; l''ATC répond « négatif, répétez [valeur masquée] ». Quelle information pouvez-vous considérer comme résolue ?', 'Your readback was 4,000 ft; ATC replies “negative, say again [blocked value]”. What can be considered resolved?', '["Le niveau prévu sur la fiche de briefing", "La différence exacte de 1 000 ft", "La présence d''un écart, mais pas le niveau corrigé", "Le niveau 4 000 ft, faute d''autre valeur entendue"]', '["The briefing-sheet level", "An exact 1,000 ft difference", "There is a discrepancy, but the corrected level is unresolved", "4,000 ft because no other value was heard"]', 'La présence d''un écart, mais pas le niveau corrigé', 'Le rejet du collationnement est reçu, sa valeur de remplacement ne l''est pas. Redemander la correction ; ni la mémoire ni une différence supposée ne comblent le message manquant.

![IR_090_001](/illustrations/ir-090-001.svg)', 'Rejection of the readback was heard, its replacement value was not. Request the correction again; memory and an assumed difference cannot fill the missing message.

![IR_090_001](/illustrations/en/ir-090-001.svg)', '["IR", "exam-mcq", "exam-subject:090"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('0ad19474-0000-4000-8000-00000ad19474', '2dfcfb72-0000-4000-8000-00002dfcfb72', 'IR', 'communications', 'communications', 'Distinguer les autorisations', 3, 3, 'Au point d''attente, autorisation « alignez-vous piste 32 et attendez ». Quelle limite doit rester dans la réponse ?', 'At the holding point, clearance “line up runway 32 and wait”. Which limit must remain in the reply?', '["Traverser 32 vers la voie opposée", "Attendre après alignement ; pas de décollage autorisé", "Maintenir avant la piste malgré l''alignement demandé", "Décoller après le précédent trafic sans autre instruction"]', '["Cross 32 to the opposite taxiway", "Wait after line-up; no take-off clearance", "Hold short despite the line-up instruction", "Take off after preceding traffic without further instruction"]', 'Attendre après alignement ; pas de décollage autorisé', 'Alignement, traversée et décollage sont différents. La limite « attendez » conserve le point d''arrêt de cette autorisation ; elle ne définit aucune condition implicite de départ.

![IR_090_001](/illustrations/ir-090-001.svg)', 'Line-up, crossing and take-off differ. “Wait” preserves the stopping point of this clearance; it creates no implicit departure condition.

![IR_090_001](/illustrations/en/ir-090-001.svg)', '["IR", "exam-mcq", "exam-subject:090"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('0ad19475-0000-4000-8000-00000ad19475', '2dfcfb72-0000-4000-8000-00002dfcfb72', 'IR', 'communications', 'communications', 'Distinguer les autorisations', 3, 3, 'Clairance d''approche reçue ; plus tard « continuez l''approche ». Aucune autorisation d''atterrir. Quel état inscrire ?', 'Approach clearance received; later “continue approach”. No landing clearance. Which state applies?', '["Approche autorisée, atterrissage encore non autorisé", "Atterrissage autorisé par la deuxième transmission", "Approche annulée en l''absence de clairance d''atterrir", "Atterrissage autorisé si la piste est visuellement libre"]', '["Approach cleared, landing not yet cleared", "Landing cleared by the second transmission", "Approach cancelled without landing clearance", "Landing cleared if runway visually clear"]', 'Approche autorisée, atterrissage encore non autorisé', '« Continuez » ne contient pas l''autorisation distincte d''atterrir. L''exercice demande la portée des messages, pas une décision de poursuite à une hauteur donnée ; cette dernière dépend de la situation réelle.

![IR_090_001](/illustrations/ir-090-001.svg)', '“Continue” does not contain separate landing clearance. This asks message scope, not whether to continue at a particular height; that decision depends on the actual situation.

![IR_090_001](/illustrations/en/ir-090-001.svg)', '["IR", "exam-mcq", "exam-subject:090"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('0ad0abb8-0000-4000-8000-00000ad0abb8', '2dfcfb72-0000-4000-8000-00002dfcfb72', 'IR', 'communications', 'communications', 'Collationner les éléments de sécurité', 3, 3, 'Clairance conditionnelle correctement émise : derrière le trafic identifié en courte finale, alignez-vous 24 derrière. Quel collationnement préserve la condition ?', 'Properly issued conditional clearance: behind identified traffic on short final, line up 24 behind. Which readback preserves the condition?', '["Alignons 24, AER452", "Après notre contrôle visuel, décollons 24, AER452", "Maintenons avant 24 puis traversons derrière, AER452", "Derrière ce trafic, alignons 24 derrière, AER452"]', '["Lining up 24, AER452", "After our visual check, taking off 24, AER452", "Holding short 24 then crossing behind, AER452", "Behind that traffic, lining up 24 behind, AER452"]', 'Derrière ce trafic, alignons 24 derrière, AER452', 'La condition est une partie de la clairance, pas un commentaire. L''omettre transforme le sens ; décollage et traversée remplacent l''action autorisée. Le trafic doit être identifié sans ambiguïté.

![IR_090_001](/illustrations/ir-090-001.svg)', 'The condition is part of clearance, not commentary. Omitting it changes meaning; take-off and crossing replace the cleared action. Traffic must be unambiguously identified.

![IR_090_001](/illustrations/en/ir-090-001.svg)', '["IR", "exam-mcq", "exam-subject:090"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('0ad19477-0000-4000-8000-00000ad19477', '2dfcfb72-0000-4000-8000-00002dfcfb72', 'IR', 'communications', 'communications', 'Distinguer les autorisations', 3, 3, 'Dernier état AER452 : cap 220, 4 000 ft, 170 kt. Message suivant pour AER425 : 160 kt. Puis AER452 : cap 230, maintenez 3 000 ft. Quel état final ?

![IR_090_001](/illustrations/ir-090-001.svg)', 'Last AER452 state: heading 220, 4,000 ft, 170 kt. Next, AER425 receives 160 kt. Then AER452 receives heading 230, maintain 3,000 ft. Final state?

![IR_090_001](/illustrations/en/ir-090-001.svg)', '["220 / 3 000 ft / 170 kt", "230 / 4 000 ft / 170 kt", "230 / 3 000 ft / 170 kt", "230 / 3 000 ft / 160 kt"]', '["220 / 3,000 ft / 170 kt", "230 / 4,000 ft / 170 kt", "230 / 3,000 ft / 170 kt", "230 / 3,000 ft / 160 kt"]', '230 / 3 000 ft / 170 kt', 'Mettre à jour les deux éléments adressés à AER452 : cap et niveau. La vitesse 160 appartient à AER425 ; conserver 170. Les deux autres distracteurs oublient une modification correctement reçue.

![IR_090_001](/illustrations/ir-090-001.svg)', 'Update AER452''s two amended items: heading and level. 160 belongs to AER425; retain 170. The other two distractors each miss a correctly received amendment.

![IR_090_001](/illustrations/en/ir-090-001.svg)', '["IR", "exam-mcq", "exam-subject:090"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO lessons (id, license, category, theme, title_fr, title_en, content_fr, content_en, difficulty, order_index, level, duration_minutes, tags, learning_objectives) VALUES
('23ea2e3b-0000-4000-8000-000023ea2e3b', 'IR', 'flight_planning', 'flight_planning', 'Préparer et actualiser un bilan IFR', 'Prepare and update an IFR flight log', '**Objectif :** Résoudre et vérifier les exercices de préparer et actualiser un bilan ifr.

## Construire le journal de navigation

![IR_033_001](/illustrations/ir-033-001.svg)

Un bilan IFR rassemble route autorisée et utilisable, distances, niveaux, vent, vitesses sol, durées et carburant. Le temps d’un segment en heures vaut distance en NM / vitesse sol en kt. Le vent de face réduit la vitesse sol pour une même vitesse vraie ; le calcul de temps utilise la vitesse sol. Exercice fictif : A–B mesure 120 NM à 120 kt, B–C 90 NM à 180 kt. Les temps valent 60 et 30 minutes, soit 90 minutes au total. Départ à 10:20 UTC : arrivée au point C à 11:50 UTC.

## Séparer les allocations de carburant

Dans l’exercice, le débit constant est de 40 L/h : A–B consomme 40 L et B–C 20 L, soit 60 L de trajet. On fournit séparément 5 L pour le roulage, 6 L d’aléa, 18 L pour le dégagement et 20 L de réserve protégée. Le total arithmétique vaut 109 L. Ces allocations sont des données fictives, pas des minima réglementaires. Pour un vol réel, déterminer chaque quantité selon le régime d’exploitation, les conditions prévues et le manuel de l’avion ; distinguer carburant total et utilisable.

## Réviser les estimées en vol

À une vitesse sol réelle de 100 kt, le segment A–B dure 72 minutes et consomme 48 L au débit supposé : le trajet augmente de 8 L. Le nouveau total, si les autres allocations restent identiques, est 117 L. Une attente supplémentaire de 12 minutes à 30 L/h exige 6 L ; l’ajouter donne 123 L. Comparer la prévision actualisée au carburant réellement utilisable, puis revoir les options avant d’entamer une marge protégée. Ne pas transformer automatiquement une réserve en autonomie disponible pour attendre.

## Vérifier la faisabilité du projet

Le calcul ne suffit pas : vérifier les données aéronautiques en vigueur, NOTAM, disponibilité des procédures et aides, météo, performances et équipements nécessaires. Une route directe plus courte n’est pas nécessairement autorisée ni compatible avec le relief. Un terrain de dégagement doit répondre aux critères applicables, pas seulement être proche. Si une autorisation, une météo ou un équipement change, réexaminer les temps, le carburant et les solutions de repli. Les informations de l’exercice ne constituent pas un dossier de vol réel.

**Format de travail :** 15 QCM de chapitre, quatre choix et une réponse correcte. La matière 033 comporte 27 questions en 75 minutes dans le tableau EASA cité. Ce chapitre ne couvre qu’une partie de la matière ; il ne constitue pas une épreuve complète. Cadre EASA, même en anglais ou avec les unités US/britanniques.

## Références

- [EASA — programme Part-FCL](https://www.easa.europa.eu/en/document-library/easy-access-rules/online-publications/easy-access-rules-aircrew-regulation-eu-no?page=8)
- [EASA — format de la matière, AMC1 ARA.FCL.300(b)](https://www.easa.europa.eu/en/document-library/easy-access-rules/online-publications/easy-access-rules-aircrew-regulation-eu-no?kw=ppl&page=67)

**Support de révision IR(A).** À faire valider par votre instructeur. Pour un vol réel, utiliser le manuel de l’avion et les publications en vigueur. Les exemples chiffrés sont pédagogiques.', '**Objective:** Solve and cross-check exercises on prepare and update an ifr flight log.

## Build the navigation log

![IR_033_001](/illustrations/en/ir-033-001.svg)

An IFR log combines a cleared and usable route, distances, levels, wind, groundspeeds, times and fuel. Segment time in hours equals distance in NM / groundspeed in kt. Headwind reduces groundspeed for the same true airspeed; time calculations use groundspeed. Fictional exercise: A–B is 120 NM at 120 kt, B–C is 90 NM at 180 kt. Times are 60 and 30 minutes, or 90 minutes total. Departing at 10:20 UTC gives arrival at point C at 11:50 UTC.

## Separate fuel allocations

The exercise uses constant flow of 40 L/h: A–B consumes 40 L and B–C 20 L, giving 60 L trip fuel. Separate supplied allocations are 5 L taxi, 6 L contingency, 18 L alternate and 20 L protected reserve. The arithmetic total is 109 L. These allocations are fictional inputs, not regulatory minima. For a real flight, determine each quantity under the applicable operating regime, expected conditions and aircraft manual; distinguish total from usable fuel.

## Revise estimates in flight

At an actual groundspeed of 100 kt, A–B takes 72 minutes and consumes 48 L at the assumed flow: trip fuel increases by 8 L. The new total, with other allocations unchanged, is 117 L. An additional 12-minute hold at 30 L/h requires 6 L; adding it gives 123 L. Compare the updated forecast with actual usable fuel, then reassess options before consuming a protected margin. Do not automatically treat reserve fuel as available holding endurance.

## Check plan feasibility

Arithmetic is not enough: check current aeronautical data, NOTAM, procedure and aid availability, weather, performance and required equipment. A shorter direct route is not necessarily cleared or compatible with terrain. An alternate must meet applicable criteria, not merely be nearby. If a clearance, weather condition or equipment status changes, reassess time, fuel and fallback options. Exercise information is not an operational flight briefing.

**Practice format:** 15 chapter MCQs, four choices and one correct answer. Subject 033 has 27 questions in 75 minutes in the cited EASA table. This chapter covers only part of the subject and is not a full paper. EASA framework, including with English or US/British units.

