INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('66e912f9-0000-4000-8000-000066e912f9', '2574c057-0000-4000-8000-00002574c057', 'IR', 'human_performance', 'human_performance', 'Recouper les références', 3, 3, 'En IMC sans horizon visible, une sensation de vol à plat suffit-elle à établir l’attitude ?', 'In IMC without a visible horizon, is a sensation of level flight sufficient to establish attitude?', '["Non, recouper les instruments fiables", "Oui, si elle dure longtemps", "Oui, si la vitesse paraît constante", "Oui, pour un pilote expérimenté"]', '["No, cross-check reliable instruments", "Yes, if prolonged", "Yes, if speed feels constant", "Yes, for an experienced pilot"]', 'Non, recouper les instruments fiables', 'Les sensations vestibulaires peuvent devenir trompeuses.

![IR_040_001](/illustrations/ir-040-001.svg)', 'Vestibular sensations may be misleading.

![IR_040_001](/illustrations/en/ir-040-001.svg)', '["IR", "exam-mcq", "exam-subject:040"]')
