INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('66e912fa-0000-4000-8000-000066e912fa', '2574c057-0000-4000-8000-00002574c057', 'IR', 'human_performance', 'human_performance', 'Recouper les références', 3, 3, 'Les canaux semi-circulaires répondent principalement aux…', 'Semicircular canals primarily respond to…', '["Accélérations linéaires seules", "Inclinaisons statiques mesurées sans ambiguïté", "Vitesses de rotation constantes ressenties indéfiniment", "Accélérations angulaires"]', '["Linear accelerations alone", "Unambiguously measured static bank angles", "Constant rotation rates sensed indefinitely", "Angular accelerations"]', 'Accélérations angulaires', 'Distinguer accélération et vitesse de rotation : la sensation peut s’atténuer pendant un virage prolongé. Les canaux ne donnent pas une mesure absolue d’inclinaison.

![IR_040_001](/illustrations/ir-040-001.svg)', 'Distinguish acceleration from rotation rate: sensation may fade during a prolonged turn. The canals do not provide an absolute bank measurement.

![IR_040_001](/illustrations/en/ir-040-001.svg)', '["IR", "exam-mcq", "exam-subject:040"]')
