INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('66e912fb-0000-4000-8000-000066e912fb', '2574c057-0000-4000-8000-00002574c057', 'IR', 'human_performance', 'human_performance', 'Recouper les références', 3, 3, 'Pourquoi une accélération longitudinale peut-elle être prise pour un changement d’assiette ?', 'Why can longitudinal acceleration be mistaken for a pitch change?', '["Les otolithes isolent parfaitement la gravité", "La vision périphérique donne toujours l’horizon réel", "Les otolithes répondent à la résultante gravité-accélération", "Les canaux semi-circulaires mesurent directement la pente"]', '["Otolith organs perfectly isolate gravity", "Peripheral vision always provides the true horizon", "Otolith organs respond to the combined gravity-acceleration vector", "Semicircular canals directly measure flight-path angle"]', 'Les otolithes répondent à la résultante gravité-accélération', 'Sans repère visuel fiable, la résultante peut être interprétée comme une inclinaison du corps. La gravité n’est pas isolée de l’accélération linéaire.

![IR_040_001](/illustrations/ir-040-001.svg)', 'Without a reliable visual reference, the resultant may be interpreted as body tilt. Gravity is not isolated from linear acceleration.

![IR_040_001](/illustrations/en/ir-040-001.svg)', '["IR", "exam-mcq", "exam-subject:040"]')
