INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('66e916bd-0000-4000-8000-000066e916bd', '2574c057-0000-4000-8000-00002574c057', 'IR', 'human_performance', 'human_performance', 'Reconnaître les illusions', 3, 3, 'Au décollage de nuit sans horizon, une forte accélération longitudinale peut créer l’impression…', 'During a night take-off without a visible horizon, strong forward acceleration can create the impression of…', '["Une assiette fiable tant que l’accélération persiste", "Une assiette plus cabrée", "Une assiette plus piquée", "Une inclinaison latérale liée au seul sens de la piste"]', '["A reliable pitch attitude while acceleration continues", "A more nose-up attitude", "A more nose-down attitude", "Bank determined solely by runway direction"]', 'Une assiette plus cabrée', 'L’illusion somatogravique peut faire croire à un cabré excessif. La réponse sûre repose sur les instruments fiables ; la sensation ne constitue pas une mesure d’assiette.

![IR_040_001](/illustrations/ir-040-001.svg)', 'The somatogravic illusion may suggest excessive pitch-up. A safe response relies on reliable instruments; sensation is not a pitch measurement.

![IR_040_001](/illustrations/en/ir-040-001.svg)', '["IR", "exam-mcq", "exam-subject:040"]')
