INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('66e916be-0000-4000-8000-000066e916be', '2574c057-0000-4000-8000-00002574c057', 'IR', 'human_performance', 'human_performance', 'Reconnaître les illusions', 3, 3, 'En accélération IMC, le pilote ressent un cabré excessif alors que les instruments fiables montrent l’assiette prévue. Quel danger présente une poussée fondée sur la seule sensation ?', 'During acceleration in IMC, the pilot feels excessive pitch-up while reliable instruments show the intended attitude. What risk comes from pushing based solely on sensation?', '["Abaisser la trajectoire alors que l’assiette était correcte", "Maintenir nécessairement la trajectoire initiale", "Corriger un décrochage démontré par cette sensation", "Rétablir une référence vestibulaire plus fiable que les instruments"]', '["Lowering the flight path when attitude was correct", "Necessarily maintaining the original flight path", "Correcting a stall proven by that sensation", "Restoring a vestibular reference more reliable than instruments"]', 'Abaisser la trajectoire alors que l’assiette était correcte', 'L’illusion somatogravique peut conduire à une commande inadaptée. Une sensation de cabré ne démontre ni incidence critique ni erreur des instruments recoupés.

![IR_040_001](/illustrations/ir-040-001.svg)', 'The somatogravic illusion may lead to an inappropriate input. A pitch-up sensation proves neither critical angle of attack nor failure of cross-checked instruments.

![IR_040_001](/illustrations/en/ir-040-001.svg)', '["IR", "exam-mcq", "exam-subject:040"]')
