INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('66e916bf-0000-4000-8000-000066e916bf', '2574c057-0000-4000-8000-00002574c057', 'IR', 'human_performance', 'human_performance', 'Reconnaître les illusions', 3, 3, 'Après un virage prolongé à droite, une remise à plat correcte aux instruments peut donner l’impression…', 'After a prolonged right turn, correctly levelling the wings on instruments may feel like…', '["Une preuve que le virage à droite continue", "Une mesure exacte d’inclinaison nulle", "Une accélération longitudinale nécessairement positive", "Un virage à gauche"]', '["Proof that the right turn continues", "An exact zero-bank measurement", "Necessarily positive longitudinal acceleration", "A left turn"]', 'Un virage à gauche', 'La sortie du virage stimule le système adapté à la rotation précédente. Suivre cette impression en rétablissant le virage initial recréerait une inclinaison réelle.

![IR_040_001](/illustrations/ir-040-001.svg)', 'Rollout stimulates the system adapted to the previous rotation. Following that sensation by restoring the original turn would recreate a real bank.

![IR_040_001](/illustrations/en/ir-040-001.svg)', '["IR", "exam-mcq", "exam-subject:040"]')
