INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('66e916c0-0000-4000-8000-000066e916c0', '2574c057-0000-4000-8000-00002574c057', 'IR', 'human_performance', 'human_performance', 'Reconnaître les illusions', 3, 3, 'En virage IMC prolongé, le pilote baisse brusquement la tête vers une carte et perçoit un basculement complexe. Mécanisme le plus évocateur ?', 'During a prolonged IMC turn, the pilot abruptly looks down at a chart and senses complex tumbling. Most suggestive mechanism?', '["Illusion de largeur de piste", "Illusion somatogravique par seule accélération rectiligne", "Illusion de Coriolis", "Autocinésie d’un point lumineux fixe"]', '["Runway-width illusion", "Somatogravic illusion from straight-line acceleration alone", "Coriolis illusion", "Autokinesis of a stationary light"]', 'Illusion de Coriolis', 'Le mouvement de tête pendant la rotation stimule plusieurs axes vestibulaires. Les autres propositions décrivent des déclencheurs différents ; ce scénario ne constitue pas un diagnostic médical.

![IR_040_001](/illustrations/ir-040-001.svg)', 'Head movement during rotation stimulates multiple vestibular axes. The alternatives describe different triggers; this scenario is not a medical diagnosis.

![IR_040_001](/illustrations/en/ir-040-001.svg)', '["IR", "exam-mcq", "exam-subject:040"]')
