INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('66e91a82-0000-4000-8000-000066e91a82', '2574c057-0000-4000-8000-00002574c057', 'IR', 'human_performance', 'human_performance', 'Distinguer les mécanismes respiratoires', 3, 3, 'En altitude, la cause de l’hypoxie hypoxique est surtout…', 'At altitude, hypoxic hypoxia is primarily caused by…', '["La seule baisse de température", "La baisse de pression partielle d’oxygène", "La disparition de tout oxygène dans l’air", "La hausse du CO₂ atmosphérique"]', '["Lower temperature alone", "Reduced oxygen partial pressure", "All oxygen disappearing from air", "Increased atmospheric CO₂"]', 'La baisse de pression partielle d’oxygène', 'La proportion d’oxygène reste voisine, mais sa pression partielle diminue.

![IR_040_001](/illustrations/ir-040-001.svg)', 'The oxygen proportion remains similar, but partial pressure decreases.

![IR_040_001](/illustrations/en/ir-040-001.svg)', '["IR", "exam-mcq", "exam-subject:040"]')
