INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('66e91a83-0000-4000-8000-000066e91a83', '2574c057-0000-4000-8000-00002574c057', 'IR', 'human_performance', 'human_performance', 'Distinguer les mécanismes respiratoires', 3, 3, 'Une ventilation excessive par rapport aux besoins métaboliques provoque notamment…', 'Ventilation excessive relative to metabolic needs particularly causes…', '["Une élimination excessive de CO₂", "Une accumulation de CO₂ par cette seule ventilation", "Une fixation du CO sur l’hémoglobine", "Une baisse obligatoire de la proportion d’oxygène ambiant"]', '["Excessive CO₂ loss", "CO₂ accumulation from that ventilation alone", "CO binding to haemoglobin", "A necessary fall in ambient oxygen proportion"]', 'Une élimination excessive de CO₂', 'L’hyperventilation abaisse le CO₂ sanguin. La fixation du CO relève d’une intoxication différente ; la composition de l’air ambiant n’est pas modifiée par ce mécanisme.

![IR_040_001](/illustrations/ir-040-001.svg)', 'Hyperventilation lowers blood CO₂. CO binding is a different poisoning mechanism; ambient air composition is not altered by this mechanism.

![IR_040_001](/illustrations/en/ir-040-001.svg)', '["IR", "exam-mcq", "exam-subject:040"]')
