INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('79f7707a-0000-4000-8000-000079f7707a', '22273e1b-0000-4000-8000-000022273e1b', 'IR', 'instrumentation', 'instrumentation', 'Choisir la référence', 3, 3, 'Aérodrome à 600 ft AMSL, avion 900 ft au-dessus de son repère. Erreurs négligées : quelle paire QNH/QFE attend-on ?', 'Aerodrome 600 ft AMSL, aircraft 900 ft above its datum. Neglecting errors, which QNH/QFE pair is expected?', '["900 ft / 1 500 ft", "900 ft / 300 ft", "1 500 ft / 600 ft", "1 500 ft / 900 ft"]', '["900 ft / 1,500 ft", "900 ft / 300 ft", "1,500 ft / 600 ft", "1,500 ft / 900 ft"]', '1 500 ft / 900 ft', 'QNH : 600 + 900 = 1 500 ft AMSL ; QFE : 900 ft au-dessus du repère. Inverser les deux confond altitude et hauteur.

![IR_022_001](/illustrations/ir-022-001.svg)', 'QNH: 600 + 900 = 1,500 ft AMSL; QFE: 900 ft above the datum. Swapping them confuses altitude and height.

![IR_022_001](/illustrations/en/ir-022-001.svg)', '["IR", "exam-mcq", "exam-subject:022"]')
