INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('79f7707b-0000-4000-8000-000079f7707b', '22273e1b-0000-4000-8000-000022273e1b', 'IR', 'instrumentation', 'instrumentation', 'Choisir la référence', 3, 3, 'Au calage standard, FL 70 représente…', 'At standard setting, FL 70 represents…', '["Toujours 7 000 ft d’altitude vraie AMSL", "7 000 ft au-dessus du repère QFE", "7 000 ft d’altitude-pression à 1013,25 hPa", "7 000 ft de hauteur terrain"]', '["Always 7,000 ft true AMSL altitude", "7,000 ft above the QFE datum", "7,000 ft pressure altitude at 1013.25 hPa", "7,000 ft terrain height"]', '7 000 ft d’altitude-pression à 1013,25 hPa', 'Le niveau utilise la référence standard, pas une hauteur terrain ni une altitude vraie constante.

![IR_022_001](/illustrations/ir-022-001.svg)', 'A flight level uses the standard reference, not terrain height or constant true altitude.

![IR_022_001](/illustrations/en/ir-022-001.svg)', '["IR", "exam-mcq", "exam-subject:022"]')
