INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('79f7707c-0000-4000-8000-000079f7707c', '22273e1b-0000-4000-8000-000022273e1b', 'IR', 'instrumentation', 'instrumentation', 'Choisir la référence', 3, 3, 'Au QFE d’un aérodrome, l’avion survole une vallée plus basse. À quoi l’indication se rapporte-t-elle ?', 'Using an aerodrome QFE, the aircraft crosses a lower valley. What is the indication referenced to?', '["À la référence 1013,25 hPa", "Au repère de ce QFE", "Au terrain sous l’avion", "Au niveau moyen de la mer"]', '["The 1013.25 hPa reference", "That QFE datum", "Terrain below the aircraft", "Mean sea level"]', 'Au repère de ce QFE', 'Le repère QFE ne se déplace pas avec le relief. Cette indication n’est pas une mesure directe de hauteur terrain.

![IR_022_001](/illustrations/ir-022-001.svg)', 'The QFE datum does not move with terrain. This indication is not a direct terrain-height measurement.

![IR_022_001](/illustrations/en/ir-022-001.svg)', '["IR", "exam-mcq", "exam-subject:022"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('79f7743e-0000-4000-8000-000079f7743e', '22273e1b-0000-4000-8000-000022273e1b', 'IR', 'instrumentation', 'instrumentation', 'Quantifier une erreur de calage', 3, 3, 'QNH réel 1000 hPa, calage 1010 hPa. Avec 27 ft/hPa, l’indication comparée au bon calage est…', 'Actual QNH 1000 hPa, setting 1010 hPa. At 27 ft/hPa, indication compared with correct setting is…', '["Environ 270 ft trop haute", "Environ 270 ft trop basse", "Environ 27 ft trop haute", "Environ 27 ft trop basse"]', '["About 270 ft too high", "About 270 ft too low", "About 27 ft too high", "About 27 ft too low"]', 'Environ 270 ft trop haute', 'Écart : 1010 − 1000 = +10 hPa. Le calage trop élevé produit une surestimation de 270 ft ; 27 ft ne correspond qu’à 1 hPa.

![IR_022_001](/illustrations/ir-022-001.svg)', 'Difference: 1010 − 1000 = +10 hPa. The excessive setting produces 270 ft overreading; 27 ft corresponds to only 1 hPa.

![IR_022_001](/illustrations/en/ir-022-001.svg)', '["IR", "exam-mcq", "exam-subject:022"]')
