INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('79f7743f-0000-4000-8000-000079f7743f', '22273e1b-0000-4000-8000-000022273e1b', 'IR', 'instrumentation', 'instrumentation', 'Quantifier une erreur de calage', 3, 3, 'Une indication de 3 000 ft surestime de 270 ft celle au bon QNH. Indication corrigée du seul calage ?', 'An indication of 3,000 ft overreads the correct-QNH indication by 270 ft. Setting-corrected indication?', '["3 270 ft", "2 970 ft", "3 000 ft", "2 730 ft"]', '["3,270 ft", "2,970 ft", "3,000 ft", "2,730 ft"]', '2 730 ft', 'Retrancher la surestimation : 3 000 − 270 = 2 730 ft. Ajouter 270 aggrave l’erreur ; cela ne corrige pas la température.

![IR_022_001](/illustrations/ir-022-001.svg)', 'Subtract the overreading: 3,000 − 270 = 2,730 ft. Adding 270 worsens the error; this does not correct temperature.

![IR_022_001](/illustrations/en/ir-022-001.svg)', '["IR", "exam-mcq", "exam-subject:022"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('79f77801-0000-4000-8000-000079f77801', '22273e1b-0000-4000-8000-000022273e1b', 'IR', 'instrumentation', 'instrumentation', 'Pression et température réelles', 3, 3, 'L’avion conserve la même indication et le même calage vers une pression plus basse. Quel risque anticiper ?', 'The aircraft keeps the same indication and setting towards lower pressure. Which risk should be anticipated?', '["Une hauteur terrain nécessairement constante", "Une compensation automatique par l’altimètre", "Une altitude vraie plus basse que ne le suggère l’indication", "Une altitude vraie nécessairement plus haute"]', '["Terrain height necessarily constant", "Automatic compensation by the altimeter", "True altitude lower than the indication suggests", "True altitude necessarily higher"]', 'Une altitude vraie plus basse que ne le suggère l’indication', 'Le calage devenu trop élevé surestime l’altitude. Une indication constante ne garantit ni altitude vraie ni marge terrain constantes.

![IR_022_001](/illustrations/ir-022-001.svg)', 'The now-excessive setting overreads altitude. Constant indication guarantees neither constant true altitude nor terrain clearance.

![IR_022_001](/illustrations/en/ir-022-001.svg)', '["IR", "exam-mcq", "exam-subject:022"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('79f77802-0000-4000-8000-000079f77802', '22273e1b-0000-4000-8000-000022273e1b', 'IR', 'instrumentation', 'instrumentation', 'Pression et température réelles', 3, 3, 'QNH correct, air plus froid que le modèle, avion au-dessus du repère : pourquoi une correction publiée peut-elle rester nécessaire ?', 'Correct QNH, air colder than the model, aircraft above the datum: why may a published correction still be needed?', '["Le QNH devient automatiquement un QFE", "L’altitude vraie peut être inférieure à l’indiquée", "Le QNH correct impose une altitude vraie identique", "L’altitude vraie est nécessairement supérieure"]', '["QNH automatically becomes QFE", "True altitude may be below indicated altitude", "Correct QNH forces true and indicated altitude to match", "True altitude must be higher"]', 'L’altitude vraie peut être inférieure à l’indiquée', 'Le QNH correct n’annule pas l’effet de la température sur l’épaisseur des couches de pression et ne transforme pas la référence en QFE.

![IR_022_001](/illustrations/ir-022-001.svg)', 'Correct QNH does not remove temperature effects on pressure-layer thickness or turn the reference into QFE.

![IR_022_001](/illustrations/en/ir-022-001.svg)', '["IR", "exam-mcq", "exam-subject:022"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('79f77803-0000-4000-8000-000079f77803', '22273e1b-0000-4000-8000-000022273e1b', 'IR', 'instrumentation', 'instrumentation', 'Pression et température réelles', 3, 3, 'Une procédure requiert une correction de basse température. Quelle méthode retenir ?', 'A procedure requires cold-temperature correction. Which method should be used?', '["La méthode publiée pour les altitudes concernées", "Augmenter arbitrairement le QNH de toute l’approche", "Appliquer 27 ft par degré Celsius", "Remplacer les altitudes par des hauteurs radioaltimétriques"]', '["The published method for the affected altitudes", "Arbitrarily raise QNH for the whole approach", "Apply 27 ft per degree Celsius", "Replace altitudes with radio-altimeter heights"]', 'La méthode publiée pour les altitudes concernées', '27 ft/hPa concerne le calage, pas la température. Changer de repère ou de grandeur ne remplace pas la correction publiée.

![IR_022_001](/illustrations/ir-022-001.svg)', '27 ft/hPa concerns setting, not temperature. Changing datum or quantity does not replace the published correction.

![IR_022_001](/illustrations/en/ir-022-001.svg)', '["IR", "exam-mcq", "exam-subject:022"]')
