INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('79f77bc5-0000-4000-8000-000079f77bc5', '22273e1b-0000-4000-8000-000022273e1b', 'IR', 'instrumentation', 'instrumentation', 'Identifier une obstruction statique', 3, 3, 'Statique piégée à 5 000 ft, calage inchangé, avion maintenant à 6 000 ft. Dans ce modèle classique, que fait l’altimètre ?', 'Static trapped at 5,000 ft, unchanged setting, aircraft now at 6,000 ft. In this conventional model, what does the altimeter do?', '["Il suit la montée avec un retard constant", "Il revient progressivement à zéro", "Il affiche l’altitude-pression correcte malgré le blocage", "Il reste à l’indication du blocage"]', '["It follows the climb with constant lag", "It gradually returns to zero", "It shows correct pressure altitude despite blockage", "It stays at the blockage indication"]', 'Il reste à l’indication du blocage', 'La pression appliquée et le calage restent fixes. Une indication figée ne doit pas être confondue avec un décalage qui continuerait à suivre la montée.

![IR_022_001](/illustrations/ir-022-001.svg)', 'Applied pressure and setting remain fixed. A frozen indication is not an offset that continues to follow the climb.

![IR_022_001](/illustrations/en/ir-022-001.svg)', '["IR", "exam-mcq", "exam-subject:022"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('44f7fc13-0000-4000-8000-000044f7fc13', '22273e1b-0000-4000-8000-000022273e1b', 'IR', 'instrumentation', 'instrumentation', 'Identifier une obstruction statique', 3, 3, 'La statique d’un variomètre classique est entièrement piégée. Après le transitoire, que peut-il indiquer malgré une montée réelle ?', 'A conventional VSI has fully trapped static pressure. After the transient, what may it indicate despite an actual climb?', '["Le dernier taux de montée indéfiniment", "Un taux de descente égal au taux réel de montée", "Zéro", "Le taux réel de montée"]', '["The last climb rate indefinitely", "A descent rate equal to actual climb rate", "Zero", "Actual climb rate"]', 'Zéro', 'Après égalisation interne, il n’y a plus de variation de pression à mesurer. Ne pas confondre ce comportement avec l’altimètre figé.

![IR_022_001](/illustrations/ir-022-001.svg)', 'After internal equalisation, no pressure change remains to measure. Do not confuse this behaviour with the frozen altimeter.

![IR_022_001](/illustrations/en/ir-022-001.svg)', '["IR", "exam-mcq", "exam-subject:022"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('44f7fc14-0000-4000-8000-000044f7fc14', '22273e1b-0000-4000-8000-000022273e1b', 'IR', 'instrumentation', 'instrumentation', 'Identifier une obstruction statique', 3, 3, 'Statique piégée à 5 000 ft, Pitot libre. Après 7 000 ft, l’avion descend à 6 000 ft. Atmosphère stable : erreur de vitesse par rapport à une statique correcte ?', 'Static trapped at 5,000 ft, pitot open. After reaching 7,000 ft, the aircraft descends to 6,000 ft. Stable atmosphere: airspeed error compared with correct static pressure?', '["Erreur indépendante de l’altitude du blocage", "Sous-indication", "Surindication", "Aucune erreur car l’avion descend"]', '["Error independent of blockage altitude", "Underreading", "Overreading", "No error because the aircraft descends"]', 'Sous-indication', '6 000 ft reste au-dessus de 5 000 ft : statique piégée trop élevée, différence mesurée trop faible. Le sens de déplacement ne suffit pas à conclure.

![IR_022_001](/illustrations/ir-022-001.svg)', '6,000 ft remains above 5,000 ft: trapped static too high, measured difference too small. Direction of motion alone cannot determine the error.

![IR_022_001](/illustrations/en/ir-022-001.svg)', '["IR", "exam-mcq", "exam-subject:022"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('44f7fc15-0000-4000-8000-000044f7fc15', '22273e1b-0000-4000-8000-000022273e1b', 'IR', 'instrumentation', 'instrumentation', 'Identifier une obstruction statique', 3, 3, 'Statique piégée à 5 000 ft, Pitot libre, avion à 4 000 ft. Atmosphère stable : erreur de vitesse par rapport à une statique correcte ?', 'Static trapped at 5,000 ft, pitot open, aircraft at 4,000 ft. Stable atmosphere: airspeed error compared with correct static pressure?', '["Surindication", "Sous-indication", "Aucune erreur car le Pitot est libre", "Vitesse nécessairement figée à celle du blocage"]', '["Overreading", "Underreading", "No error because the pitot is open", "Airspeed necessarily frozen at blockage value"]', 'Surindication', 'Au-dessous du blocage, statique piégée trop faible et différence mesurée trop grande. Un Pitot libre ne corrige pas une référence statique erronée.

![IR_022_001](/illustrations/ir-022-001.svg)', 'Below blockage altitude, trapped static is too low and measured difference too large. An open pitot cannot correct an erroneous static reference.

![IR_022_001](/illustrations/en/ir-022-001.svg)', '["IR", "exam-mcq", "exam-subject:022"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('44f7fc16-0000-4000-8000-000044f7fc16', '22273e1b-0000-4000-8000-000022273e1b', 'IR', 'instrumentation', 'instrumentation', 'Identifier une obstruction statique', 3, 3, 'Après sélection d’une statique de secours, les indications changent légèrement. Quelle interprétation retenir ?', 'After selecting alternate static, indications change slightly. Which interpretation is appropriate?', '["Tout changement prouve une panne de la source de secours", "Les indications deviennent exactes sans correction", "Il faut toujours modifier le QNH d’une valeur fixe", "La nouvelle source peut nécessiter les corrections du manuel"]', '["Any change proves the alternate source has failed", "Indications become exact without correction", "QNH must always be changed by a fixed amount", "The new source may require manual corrections"]', 'La nouvelle source peut nécessiter les corrections du manuel', 'La pression dépend de l’installation : utiliser ses corrections et sa procédure. Le changement seul ne prouve ni exactitude parfaite ni panne certaine.

![IR_022_001](/illustrations/ir-022-001.svg)', 'Pressure depends on the installation: use its corrections and procedure. Change alone proves neither perfect accuracy nor definite failure.

![IR_022_001](/illustrations/en/ir-022-001.svg)', '["IR", "exam-mcq", "exam-subject:022"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('44f7fc17-0000-4000-8000-000044f7fc17', '22273e1b-0000-4000-8000-000022273e1b', 'IR', 'instrumentation', 'instrumentation', 'Identifier une obstruction statique', 3, 3, 'Une procédure impose une altitude barométrique AMSL. Peut-on y substituer directement une hauteur radioaltimétrique fiable ?', 'A procedure specifies barometric AMSL altitude. Can a reliable radio-altimeter height be substituted directly?', '["Oui, si le QNH a été confirmé", "Oui, en descente stabilisée", "Non, les repères diffèrent", "Oui, une mesure fiable a toujours le même repère"]', '["Yes, if QNH has been confirmed", "Yes, in a steady descent", "No, the datums differ", "Yes, a reliable measurement always has the same datum"]', 'Non, les repères diffèrent', 'La radioaltimétrie mesure une hauteur terrain. Fiabilité de la mesure et pertinence de la grandeur sont deux vérifications différentes.

![IR_022_001](/illustrations/ir-022-001.svg)', 'Radio altimetry measures terrain height. Measurement reliability and relevance of the quantity are separate checks.

![IR_022_001](/illustrations/en/ir-022-001.svg)', '["IR", "exam-mcq", "exam-subject:022"]')
