INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('38cc519a-0000-4000-8000-000038cc519a', '272998f6-0000-4000-8000-0000272998f6', 'IR', 'meteorology', 'meteorology', 'Identifier les conditions', 3, 3, 'L’isotherme 0 °C est prévu à 5 000 ft, mais un profil local révèle une inversion. Quelle information évalue le mieux une couche à 7 000 ft ?', 'The freezing level is forecast at 5,000 ft, but a local profile shows an inversion. Which information best assesses a layer at 7,000 ft?', '["Un gradient standard appliqué uniquement aux 2 000 ft d’écart", "La température au sol extrapolée sans considérer l’inversion", "La première altitude de 0 °C prise comme frontière unique", "Le profil de température et l’eau liquide à ce niveau"]', '["A standard lapse rate applied only to the 2,000 ft difference", "Surface temperature extrapolated without considering the inversion", "The first 0 °C altitude treated as the only boundary", "Temperature profile and liquid water at that level"]', 'Le profil de température et l’eau liquide à ce niveau', 'L’inversion peut produire plusieurs passages à 0 °C. Il faut examiner la couche visée, avec son eau liquide. Les autres choix remplacent le profil réel par une simplification qui écarte précisément la donnée nouvelle.

![IR_050_001](/illustrations/ir-050-001.svg)', 'An inversion may produce several crossings of 0 °C. Examine the target layer and its liquid water. The other choices replace the actual profile with a simplification that discards the new evidence.

![IR_050_001](/illustrations/en/ir-050-001.svg)', '["IR", "exam-mcq", "exam-subject:050"]')
