INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('38cc519b-0000-4000-8000-000038cc519b', '272998f6-0000-4000-8000-0000272998f6', 'IR', 'meteorology', 'meteorology', 'Identifier les conditions', 3, 3, 'Deux observations à −5 °C : A, dix minutes dans un nuage ; B, cinq minutes dans un autre. Quelle donnée supplémentaire est nécessaire pour comparer les dépôts, à avion identique ?', 'Two observations at −5 °C: A, ten minutes in cloud; B, five minutes in another cloud. What additional data is needed to compare deposits on the same aircraft type?', '["Seulement l''égalité de température", "Seulement l''altitude pression de chaque vol", "Eau liquide et caractéristiques des gouttes dans chaque nuage", "Seulement la durée totale déjà fournie"]', '["Only the equal temperature", "Only each flight''s pressure altitude", "Liquid water and droplet characteristics in each cloud", "Only the total duration already supplied"]', 'Eau liquide et caractéristiques des gouttes dans chaque nuage', 'L''exposition est plus longue en A mais les nuages ne sont pas caractérisés. Une accumulation dépend aussi de l''eau et des gouttes ; ni température égale ni altitude seule ne rend les taux de dépôt comparables.

![IR_050_001](/illustrations/ir-050-001.svg)', 'Exposure is longer in A, but the clouds are uncharacterised. Accumulation also depends on water and droplets; equal temperature or altitude alone cannot establish comparable deposition rates.

![IR_050_001](/illustrations/en/ir-050-001.svg)', '["IR", "exam-mcq", "exam-subject:050"]')
