INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('38cc519c-0000-4000-8000-000038cc519c', '272998f6-0000-4000-8000-0000272998f6', 'IR', 'meteorology', 'meteorology', 'Identifier les conditions', 3, 3, 'De la pluie traverse une couche positive puis une couche sous 0 °C en restant liquide. Quelle interprétation décrit le danger d’impact ?', 'Rain crosses an above-freezing layer, then a subzero layer while remaining liquid. Which interpretation describes the impact hazard?', '["Le risque dépend uniquement de la température à l’aérodrome", "Les gouttes surfondues peuvent geler sur les surfaces rencontrées", "La couche chaude supprime le risque dans la couche froide suivante", "La pluie devient nécessairement neige dès le passage sous 0 °C"]', '["Risk depends only on temperature at the aerodrome", "Supercooled drops may freeze on surfaces they strike", "The warm layer removes risk in the following cold layer", "Rain necessarily becomes snow as soon as it crosses below 0 °C"]', 'Les gouttes surfondues peuvent geler sur les surfaces rencontrées', 'L’eau reste liquide d’après l’énoncé : elle est surfondue dans la couche froide. La couche chaude précédente ne protège pas la suite du trajet. La température au sol ne décrit pas ce profil vertical.

![IR_050_001](/illustrations/ir-050-001.svg)', 'The stem says the water remains liquid: it is supercooled in the cold layer. The preceding warm layer does not protect the rest of the route. Surface temperature does not describe this vertical profile.

![IR_050_001](/illustrations/en/ir-050-001.svg)', '["IR", "exam-mcq", "exam-subject:050"]')
