INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('38cc555e-0000-4000-8000-000038cc555e', '272998f6-0000-4000-8000-0000272998f6', 'IR', 'meteorology', 'meteorology', 'Distinguer les dépôts', 3, 3, 'Un dépôt devient blanc, opaque et rugueux. Quel mécanisme est le plus compatible avec cette observation ?', 'A deposit becomes white, opaque and rough. Which mechanism best matches this observation?', '["Une congélation rapide emprisonnant de l’air", "Un étalement prolongé avant congélation donnant surtout une couche transparente", "Une fonte complète suivie d’évaporation sans dépôt", "Une condensation liquide restant au-dessus de 0 °C"]', '["Rapid freezing trapping air", "Prolonged spreading before freezing, mainly producing a transparent layer", "Complete melting followed by evaporation without a deposit", "Liquid condensation remaining above 0 °C"]', 'Une congélation rapide emprisonnant de l’air', 'L’aspect évoque le givre blanc. L’étalement avant congélation correspond plutôt au verglas. Identifier le mécanisme n’autorise pas à classer le dépôt comme bénin : position, forme et effets restent à examiner.

![IR_050_001](/illustrations/ir-050-001.svg)', 'The appearance suggests rime. Spreading before freezing is more characteristic of clear ice. Identifying the mechanism does not make the deposit harmless: location, shape and effects still matter.

![IR_050_001](/illustrations/en/ir-050-001.svg)', '["IR", "exam-mcq", "exam-subject:050"]')
