INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('38cc555f-0000-4000-8000-000038cc555f', '272998f6-0000-4000-8000-0000272998f6', 'IR', 'meteorology', 'meteorology', 'Distinguer les dépôts', 3, 3, 'Un dépôt transparent est difficile à distinguer sur une surface mal éclairée. Quelle conclusion est fondée ?', 'A transparent deposit is difficult to distinguish on a poorly lit surface. Which conclusion is justified?', '["Une faible visibilité du dépôt indique une faible accumulation", "Un dépôt transparent est moins dangereux à toute épaisseur", "L’absence de rugosité visible prouve le maintien du profil initial", "La visibilité du dépôt ne quantifie pas sa gravité"]', '["Poor deposit visibility indicates little accumulation", "A transparent deposit is less hazardous at every thickness", "No visible roughness proves the original profile is maintained", "Deposit visibility does not quantify severity"]', 'La visibilité du dépôt ne quantifie pas sa gravité', 'Éclairage et aspect limitent l’observation. Celle-ci ne mesure ni épaisseur, ni géométrie, ni effets. Les autres propositions transforment une difficulté de détection en preuve de sécurité ; il faut poursuivre la surveillance adaptée.

![IR_050_001](/illustrations/ir-050-001.svg)', 'Lighting and appearance limit observation. It measures neither thickness, geometry nor effects. The other choices turn detection difficulty into evidence of safety; appropriate monitoring must continue.

![IR_050_001](/illustrations/en/ir-050-001.svg)', '["IR", "exam-mcq", "exam-subject:050"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('38cc5560-0000-4000-8000-000038cc5560', '272998f6-0000-4000-8000-0000272998f6', 'IR', 'meteorology', 'meteorology', 'Distinguer les dépôts', 3, 3, 'Le dégivrage nettoie sa zone, mais une bande de glace apparaît derrière la surface protégée. Quelle interprétation doit guider la réévaluation ?', 'De-icing clears its own area, but a band of ice appears aft of the protected surface. Which interpretation should guide reassessment?', '["La bande prouve nécessairement une panne électrique du dégivrage", "La protection des sondes compense cette accumulation", "L’accumulation peut dépasser la zone que le système protège", "Le nettoyage du bord d’attaque prouve la maîtrise du dépôt total"]', '["The band necessarily proves an electrical de-icing failure", "Probe protection compensates for this accumulation", "Accumulation may extend beyond the area protected by the system", "A clear leading edge proves control of the entire deposit"]', 'L’accumulation peut dépasser la zone que le système protège', 'Le système peut fonctionner localement sans maîtriser les zones arrière. Appliquer les procédures et réévaluer la sortie ; cette observation ne diagnostique pas à elle seule une panne électrique ni un type exact de gouttes.

![IR_050_001](/illustrations/ir-050-001.svg)', 'The system may work locally without controlling aft areas. Apply procedures and reassess the exit; this observation alone diagnoses neither electrical failure nor an exact droplet type.

![IR_050_001](/illustrations/en/ir-050-001.svg)', '["IR", "exam-mcq", "exam-subject:050"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('38cc5561-0000-4000-8000-000038cc5561', '272998f6-0000-4000-8000-0000272998f6', 'IR', 'meteorology', 'meteorology', 'Distinguer les dépôts', 3, 3, 'Exercice de préparation : le manuel de l’avion exclut la pluie verglaçante. Le trajet prévu en rencontre, mais tous les équipements fonctionnent. Quelle décision respecte ces données ?', 'Planning exercise: the aircraft manual excludes freezing rain. The planned route encounters it, but all equipment works. Which decision respects these inputs?', '["Remplacer la restriction par un compte rendu favorable d’un autre type d’avion", "Modifier le projet pour éviter les conditions exclues", "Garder le trajet en activant tous les équipements plus tôt", "Garder le trajet si l’exposition dure moins de cinq minutes"]', '["Replace the restriction with a favourable report from another aircraft type", "Change the plan to avoid the excluded conditions", "Keep the route and activate all equipment earlier", "Keep the route if exposure lasts under five minutes"]', 'Modifier le projet pour éviter les conditions exclues', 'La restriction est explicite : équipement fonctionnel ne signifie pas domaine illimité. Ni un délai inventé de cinq minutes ni l’expérience d’un autre avion ne modifient ce manuel. La décision se prend ici avant exposition.

![IR_050_001](/illustrations/ir-050-001.svg)', 'The restriction is explicit: functioning equipment does not mean an unlimited envelope. Neither an invented five-minute allowance nor another aircraft’s experience changes the manual. This decision is made before exposure.

![IR_050_001](/illustrations/en/ir-050-001.svg)', '["IR", "exam-mcq", "exam-subject:050"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('38cc5923-0000-4000-8000-000038cc5923', '272998f6-0000-4000-8000-0000272998f6', 'IR', 'meteorology', 'meteorology', 'Comprendre les effets', 3, 3, 'En accumulation observée, altitude, configuration et puissance restent constantes tandis que l''IAS baisse. Quel raisonnement distingue effet possible et preuve ?', 'During observed accumulation, altitude, configuration and power stay constant while IAS falls. Which reasoning separates a possible effect from proof?', '["Une hausse de traînée est cohérente, à recouper avec les autres paramètres", "La baisse d''IAS mesure directement la nouvelle vitesse de décrochage", "La baisse d''IAS quantifie à elle seule la masse de glace", "L''altitude constante prouve que la portance maximale est inchangée"]', '["Increased drag is consistent and needs cross-checking", "Falling IAS directly measures the new stall speed", "Falling IAS alone quantifies ice mass", "Constant altitude proves maximum lift is unchanged"]', 'Une hausse de traînée est cohérente, à recouper avec les autres paramètres', 'La tendance est compatible avec une augmentation de traînée mais ne fournit ni vitesse de décrochage ni masse déposée. Maintenir la portance nécessaire au palier ne mesure pas la portance maximale disponible.

![IR_050_001](/illustrations/ir-icing-effects.svg)', 'The trend is consistent with increased drag but supplies neither stall speed nor deposited mass. Maintaining lift needed for level flight does not measure maximum available lift.

![IR_050_001](/illustrations/en/ir-icing-effects.svg)', '["IR", "exam-mcq", "exam-subject:050"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('38cc5924-0000-4000-8000-000038cc5924', '272998f6-0000-4000-8000-0000272998f6', 'IR', 'meteorology', 'meteorology', 'Comprendre les effets', 3, 3, 'Sous pilote automatique, l’altitude reste stable mais l’IAS décroît pendant une accumulation. Que démontre l’altitude stable ?', 'On autopilot, altitude remains stable but IAS decreases during accumulation. What does stable altitude establish?', '["Une marge au décrochage constante", "L’absence d’effet aérodynamique puisque la trajectoire est tenue", "L’efficacité de tous les dispositifs de protection", "Seulement le maintien d’altitude observé, pas celui des marges"]', '["A constant stall margin", "No aerodynamic effect because the flight path is maintained", "Effectiveness of all protection systems", "Only observed altitude holding, not preservation of margins"]', 'Seulement le maintien d’altitude observé, pas celui des marges', 'Un paramètre maintenu peut masquer la tendance des autres. La baisse d’IAS doit être recoupée et traitée selon les procédures de l’avion. L’altitude ne mesure ni le dépôt ni la marge de vitesse.

![IR_050_001](/illustrations/ir-icing-effects.svg)', 'One maintained parameter can hide trends in others. Decreasing IAS must be cross-checked and handled under aircraft procedures. Altitude measures neither accumulation nor airspeed margin.

![IR_050_001](/illustrations/en/ir-icing-effects.svg)', '["IR", "exam-mcq", "exam-subject:050"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('60beca94-0000-4000-8000-000060beca94', '272998f6-0000-4000-8000-0000272998f6', 'IR', 'meteorology', 'meteorology', 'Comprendre les effets', 3, 3, 'Deux chaînes IAS indépendantes concordent et les sondes sont chauffées. Une aile présente une contamination visible. Quelle question reste non résolue par cet accord instrumental ?', 'Two independent IAS chains agree and probes are heated. A wing is visibly contaminated. Which question remains unresolved by instrument agreement?', '["La présence de contamination signalée dans l''énoncé", "La valeur numérique affichée par chaque chaîne", "La marge aérodynamique de l''aile contaminée", "La concordance actuelle entre les deux IAS"]', '["Presence of the stated visible contamination", "The numerical value displayed by each chain", "Aerodynamic margin of the contaminated wing", "Current agreement between both IAS values"]', 'La marge aérodynamique de l''aile contaminée', 'L''accord renseigne sur la cohérence des mesures, pas sur la portance maximale du profil contaminé. Les autres propositions sont des observations déjà données, non l''inconnue à préserver dans le raisonnement.

![IR_050_001](/illustrations/ir-icing-effects.svg)', 'Agreement informs measurement consistency, not the contaminated aerofoil''s maximum lift. The other choices are already supplied observations, not the remaining unknown.

![IR_050_001](/illustrations/en/ir-icing-effects.svg)', '["IR", "exam-mcq", "exam-subject:050"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('60bf3ef4-0000-4000-8000-000060bf3ef4', '272998f6-0000-4000-8000-0000272998f6', 'IR', 'meteorology', 'meteorology', 'Préparer une sortie', 3, 3, 'Un manuel prescrit l’activation d’un système avant l’entrée dans les conditions concernées. Quel raisonnement respecte la consigne ?', 'A manual requires system activation before entering the relevant conditions. Which reasoning respects the instruction?', '["Retarder l’activation jusqu’à une baisse mesurable de vitesse", "Prévenir l’accumulation en suivant le déclenchement prescrit", "Attendre une épaisseur visible pour confirmer l’utilité du système", "Transposer le cycle d’un autre avion équipé de boudins"]', '["Delay activation until measurable speed loss", "Prevent accumulation using the prescribed activation trigger", "Wait for visible thickness to confirm the system is useful", "Copy the cycle from another aircraft equipped with boots"]', 'Prévenir l’accumulation en suivant le déclenchement prescrit', 'Le déclenchement est fourni : ne pas le remplacer par un seuil personnel. Attendre glace ou perte de vitesse transforme la prévention en réaction tardive. Les systèmes n’ont pas tous les mêmes procédures.

![IR_050_001](/illustrations/ir-050-001.svg)', 'The activation trigger is supplied: do not replace it with a personal threshold. Waiting for ice or speed loss turns prevention into a late reaction. Different systems need not use the same procedures.

![IR_050_001](/illustrations/en/ir-050-001.svg)', '["IR", "exam-mcq", "exam-subject:050"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('60bf3ef5-0000-4000-8000-000060bf3ef5', '272998f6-0000-4000-8000-0000272998f6', 'IR', 'meteorology', 'meteorology', 'Préparer une sortie', 3, 3, 'La prévision annonçait peu de risque, mais une accumulation nouvelle s’étend hors des zones protégées. Quel élément impose de réexaminer le plan ?', 'The forecast suggested little risk, but new accumulation extends beyond protected areas. Which evidence calls for reassessment of the plan?', '["L’observation actuelle et son évolution sur cet avion", "L’absence de signalement une heure auparavant", "Le seul classement peu risqué retenu au briefing", "Le fonctionnement apparent du système dans sa zone"]', '["Current observation and its trend on this aircraft", "No report one hour earlier", "Only the low-risk classification used in the briefing", "The system apparently working in its own area"]', 'L’observation actuelle et son évolution sur cet avion', 'L’observation remet en cause les hypothèses du plan. Appliquer les procédures et réévaluer la sortie sans attendre une nouvelle prévision. Un système actif et un ancien compte rendu ne neutralisent pas le dépôt constaté.

![IR_050_001](/illustrations/ir-050-001.svg)', 'The observation challenges assumptions behind the plan. Apply procedures and reassess the exit without waiting for a new forecast. An active system and an old report do not negate the deposit observed.

![IR_050_001](/illustrations/en/ir-050-001.svg)', '["IR", "exam-mcq", "exam-subject:050"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('60bf3ef6-0000-4000-8000-000060bf3ef6', '272998f6-0000-4000-8000-0000272998f6', 'IR', 'meteorology', 'meteorology', 'Préparer une sortie', 3, 3, 'Sorties fictives, profils fixes : A 12 NM à GS 120 kt, altitude 6 500 ft/minimum 7 000 ; B 21 NM à GS 140 kt, 8 000/7 000 ; C 16 NM à GS 120 kt, 8 000/7 000, consommation 10 kg. Carburant utilisable pour ces segments après protection des besoins ultérieurs : 8 kg ; B consomme 7 kg. Météo, performances et autres contraintes vérifiées. Quelle option satisfait altitude et carburant ?

![IR_050_001](/illustrations/ir-050-001.svg)', 'Fictional exits, fixed profiles: A 12 NM at GS 120 kt, altitude 6,500 ft/minimum 7,000; B 21 NM at GS 140 kt, 8,000/7,000; C 16 NM at GS 120 kt, 8,000/7,000, consumption 10 kg. Fuel usable for these segments after protecting later requirements: 8 kg; B uses 7 kg. Weather, performance and other constraints checked. Which meets altitude and fuel limits?

![IR_050_001](/illustrations/en/ir-050-001.svg)', '["A, 6 minutes", "C, 8 minutes", "B, 21 minutes", "B, 9 minutes"]', '["A, 6 minutes", "C, 8 minutes", "B, 21 minutes", "B, 9 minutes"]', 'B, 9 minutes', 'A viole le minimum ; C exige 10 kg pour 8 disponibles. B respecte les deux contraintes et demande 60 × 21/140 = 9 minutes. La durée la plus courte n''est pas la première sélection ; les besoins ultérieurs sont protégés par hypothèse, pas supposés nuls.

![IR_050_001](/illustrations/ir-050-001.svg)', 'A violates the minimum; C needs 10 kg with 8 available. B meets both constraints and takes 60 × 21/140 = 9 minutes. Shortest time is not the first filter; later fuel requirements are protected by assumption, not assumed zero.

![IR_050_001](/illustrations/en/ir-050-001.svg)', '["IR", "exam-mcq", "exam-subject:050"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO questions (id, lesson_id, license, category, theme, subtopic, difficulty, level, question_fr, question_en, options, options_en, answer_key, explanation_fr, explanation_en, tags) VALUES
('60bf3ef7-0000-4000-8000-000060bf3ef7', '272998f6-0000-4000-8000-0000272998f6', 'IR', 'meteorology', 'meteorology', 'Préparer une sortie', 3, 3, 'Route A sort du nuage en 5 minutes mais exige une montée dont la faisabilité en conditions givrantes n''est pas établie. B sort en 10 minutes avec contraintes vérifiées. Que manque-t-il pour comparer A comme option admissible ?', 'Route A exits cloud in five minutes but requires a climb whose feasibility in icing is unestablished. B exits in ten minutes with constraints checked. What is missing before treating A as admissible?', '["Un compte rendu favorable d''un autre avion à un autre niveau", "La confirmation que cinq minutes sont inférieures à dix", "La capacité de montée de cet avion dans ces conditions", "Un calcul plus précis des cinq minutes seulement"]', '["A favourable report from another aircraft at another level", "Confirmation that five minutes is less than ten", "This aircraft''s climb capability in those conditions", "Only a more precise five-minute calculation"]', 'La capacité de montée de cet avion dans ces conditions', 'La contrainte inconnue est la montée. Une durée avantageuse ou un compte rendu non représentatif ne l''établit pas. L''exercice ne demande pas d''inventer une performance ; conserver explicitement cette incertitude avant de comparer les options.

![IR_050_001](/illustrations/ir-050-001.svg)', 'The unknown constraint is climb capability. A shorter duration or unrepresentative report does not establish it. Do not invent performance; retain the uncertainty before comparing options.

![IR_050_001](/illustrations/en/ir-050-001.svg)', '["IR", "exam-mcq", "exam-subject:050"]')
ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, license = EXCLUDED.license, category = EXCLUDED.category, theme = EXCLUDED.theme, subtopic = EXCLUDED.subtopic, difficulty = EXCLUDED.difficulty, level = EXCLUDED.level, question_fr = EXCLUDED.question_fr, question_en = EXCLUDED.question_en, options = EXCLUDED.options, options_en = EXCLUDED.options_en, answer_key = EXCLUDED.answer_key, explanation_fr = EXCLUDED.explanation_fr, explanation_en = EXCLUDED.explanation_en, tags = EXCLUDED.tags;

INSERT INTO lessons (id, license, category, theme, title_fr, title_en, content_fr, content_en, difficulty, order_index, level, duration_minutes, tags, learning_objectives) VALUES
('28faa097-0000-4000-8000-000028faa097', 'IR', 'navigation', 'navigation', 'VOR et distance oblique DME', 'VOR and DME slant range', '**Objectif :** Résoudre et vérifier les exercices de vor et distance oblique dme.

## Radial et route vers la station

![IR_062_001](/illustrations/ir-062-001.svg)

Un radial VOR est une direction depuis la station, généralement référencée au nord magnétique de la station. Un avion à l’est sur le radial 090 peut suivre une route 270 vers la station : radial et route suivie sont différents. Le cap dépend aussi du vent. Pour les exercices, tous les angles utilisent la même référence magnétique, sans écart de déclinaison entre avion et station. Identifier la station, vérifier sa disponibilité et la validité des indications avant emploi.

## Interpréter TO/FROM

Sur le radial 090 et exactement sur l’axe, OBS 090 donne FROM ; OBS 270 donne TO, hors zone d’ambiguïté et avec signal valide. TO/FROM se rapporte à la route sélectionnée et à la position, pas au cap instantané. Une aiguille centrée ne prouve donc pas que l’avion se dirige vers la station. Vérifier ensemble route sélectionnée, drapeau TO/FROM, position et suivi de route. Ne pas déduire une autorisation de procédure de la seule présence d’un signal.

## Calculer la distance oblique

Le DME mesure la distance oblique entre les antennes. Dans le modèle géométrique local : s² = d² + h², avec s distance DME, d distance horizontale et h différence de hauteur entre avion et station, toutes dans la même unité. Exemple fictif : d = 4 NM et h = 3 NM donnent s = 5 NM. À la verticale, s = h, pas zéro. Pour convertir la hauteur, utiliser 1 NM = 6 076 ft environ ; soustraire l’altitude de la station à celle de l’avion. Les arrondis de cet exercice ne sont pas une spécification de précision du récepteur.

## Reconnaître les limites

L’écart entre distance oblique et horizontale est surtout sensible près de la verticale et à grande hauteur relative. Le DME ne donne pas un cap. L’affichage de vitesse dérivé de la variation de distance ne représente pas nécessairement la vitesse sol : en arc à distance constante, l’avion se déplace alors que la distance varie peu. Même en route vers la station, l’effet de distance oblique devient important près de celle-ci. Un DME d’approche peut être installé ailleurs qu’au seuil : utiliser la référence publiée. Les principes techniques sont universels ; les procédures et autorisations restent celles du cadre EASA et des publications applicables.

**Format de travail :** 15 QCM de chapitre, quatre choix et une réponse correcte. La matière 062 comporte 44 questions en 60 minutes dans le tableau EASA cité. Ce chapitre ne couvre qu’une partie de la matière ; il ne constitue pas une épreuve complète. Cadre EASA, même en anglais ou avec les unités US/britanniques.

## Références

- [EASA — programme Part-FCL](https://www.easa.europa.eu/en/document-library/easy-access-rules/online-publications/easy-access-rules-aircrew-regulation-eu-no?page=8)
- [EASA — format de la matière, AMC1 ARA.FCL.300(b)](https://www.easa.europa.eu/en/document-library/easy-access-rules/online-publications/easy-access-rules-aircrew-regulation-eu-no?kw=ppl&page=67)
- [FAA AIM — principes techniques VOR/DME uniquement](https://www.faa.gov/air_traffic/publications/aim_html/chap1_section_1.html)

**Support de révision IR(A).** À faire valider par votre instructeur. Pour un vol réel, utiliser le manuel de l’avion et les publications en vigueur. Les exemples chiffrés sont pédagogiques.', '**Objective:** Solve and cross-check exercises on vor and dme slant range.

## Radial and course to the station

![IR_062_001](/illustrations/en/ir-062-001.svg)

A VOR radial is a direction from the station, normally referenced to station magnetic north. An aircraft east of the station on radial 090 can track 270 towards it: radial and flown course differ. Heading also depends on wind. Exercise angles use the same magnetic reference, with no variation difference between aircraft and station. Identify the station and check availability and indication validity before use.

## Interpret TO/FROM

On radial 090 and exactly on the course line, OBS 090 gives FROM; OBS 270 gives TO, outside ambiguity areas with a valid signal. TO/FROM relates to selected course and position, not instantaneous heading. A centred needle therefore does not prove the aircraft is moving towards the station. Cross-check selected course, TO/FROM flag, position and tracking. Signal reception alone does not authorise a procedure.

## Calculate slant range

DME measures slant range between antennas. In the local geometric model: s² = d² + h², where s is DME range, d horizontal distance and h aircraft-to-station height difference, all in the same unit. Fictional example: d = 4 NM and h = 3 NM give s = 5 NM. Directly overhead, s = h, not zero. For height conversion use approximately 1 NM = 6,076 ft; subtract station elevation from aircraft altitude. Exercise rounding is not a receiver accuracy specification.

## Recognise limitations

Slant-versus-horizontal difference is most noticeable near overhead and at large relative height. DME does not provide heading. Speed derived from changing range need not equal groundspeed: on a constant-range arc, the aircraft moves while range changes little. Even when tracking towards the station, slant geometry matters close to it. An approach DME may be located away from the threshold: use the published reference. Technical principles are universal; procedures and approvals remain those of the EASA framework and applicable publications.

**Practice format:** 15 chapter MCQs, four choices and one correct answer. Subject 062 has 44 questions in 60 minutes in the cited EASA table. This chapter covers only part of the subject and is not a full paper. EASA framework, including with English or US/British units.

